// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Bound the amount to avoid overflow and ensure it's feasible
        amount = bound(amount, 0.001 ether, 50 ether);
        vm.assume(recipient != address(this));

        // 2. Setup: fund the contract via fallback and call withdrawAll as owner
        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;
        // owner is address(this) because setUp deployed C with that argument
        c.withdrawAll(recipient);
        uint256 balanceAfter = address(c).balance;

        // 3. Assert: the contract's balance must be zero after withdrawal
        assertTrue(balanceBefore == 0 || balanceAfter == 0);
    }
}

