pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address recipient, uint256 seed) public {
        vm.assume(owner != address(0));
        vm.assume(recipient != address(0));
        vm.assume(owner != recipient);
        vm.assume(owner != address(this));
        vm.assume(seed > 0);
        uint256 initialAmount = seed % address(this).balance;
        vm.deal(address(this), initialAmount);
        vm.deal(address(c), initialAmount);
        uint256 recipientBalanceBefore = recipient.balance;
        vm.prank(owner);
        c.withdrawAll(recipient);
        assertTrue(recipient.balance == recipientBalanceBefore + initialAmount);
    }
}

