// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _owner, address _recipient, uint256 _funding, uint256 _unrelatedBalance) public {
        vm.assume(_owner != address(this));
        vm.assume(_recipient != address(this));
        vm.assume(_funding <= type(uint128).max);
        vm.assume(_unrelatedBalance <= type(uint128).max);

        // Restrict to avoid collisions with precompile addresses or the zero address
        vm.assume(_owner != address(0));
        vm.assume(_recipient != address(0));
        vm.assume(_owner.code.length == 0);
        vm.assume(_recipient.code.length == 0);
        vm.assume(_owner != _recipient);

        // Deploy a fresh C with a specific owner
        c = new C(_owner);

        // Fund the contract
        vm.deal(address(this), _funding);
        (bool s,) = address(c).call{value: _funding}("");
        require(s);

        // Give recipient an unrelated starting balance
        vm.deal(_recipient, _unrelatedBalance);

        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = _recipient.balance;

        // Owner calls withdrawAll
        vm.prank(_owner);
        c.withdrawAll(_recipient);

        uint256 recipientBalanceAfter = _recipient.balance;
        // The recipient's balance must increase by exactly the contract's balance before the call
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + contractBalanceBefore);
    }
}
